<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class ReportService { public function appointmentsWithDoctorPatient(){ return DB::table('appointments')->join('patients','appointments.patient_id','=','patients.id')->join('users as patient_users','patients.user_id','=','patient_users.id')->join('doctors','appointments.doctor_id','=','doctors.id')->join('users as doctor_users','doctors.user_id','=','doctor_users.id')->select('appointments.id','appointments.appointment_date','appointments.status','patient_users.name as patient_name','doctor_users.name as doctor_name')->get(); } public function doctorsWithSchedules(){ return DB::table('doctors')->join('users','doctors.user_id','=','users.id')->leftJoin('schedules','doctors.id','=','schedules.doctor_id')->select('doctors.id','users.name','doctors.specialization','schedules.day_of_week','schedules.start_time','schedules.end_time')->orderBy('users.name')->get(); } public function medicalRecordReport(){ return DB::table('medical_records')->join('appointments','medical_records.appointment_id','=','appointments.id')->join('patients','appointments.patient_id','=','patients.id')->join('users as patient_users','patients.user_id','=','patient_users.id')->join('doctors','medical_records.doctor_id','=','doctors.id')->join('users as doctor_users','doctors.user_id','=','doctor_users.id')->select('appointments.appointment_date','patient_users.name as patient_name','doctor_users.name as doctor_name','doctors.specialization','medical_records.diagnosis','medical_records.prescription')->orderByDesc('appointments.appointment_date')->get(); } }
